use crate::color_space::RGB;

const SIGNIFICANT_DIGITS: usize = 6;

pub fn format_rgb(rgb: RGB) -> String {
    format!(
        "{} {} {}",
        format_cpp_float(rgb.r),
        format_cpp_float(rgb.g),
        format_cpp_float(rgb.b)
    )
}

pub fn format_cpp_float(value: f32) -> String {
    if value.is_nan() {
        return if value.is_sign_negative() {
            String::from("-nan")
        } else {
            String::from("nan")
        };
    }

    if value.is_infinite() {
        return if value.is_sign_negative() {
            String::from("-inf")
        } else {
            String::from("inf")
        };
    }

    if value == 0.0 {
        return if value.is_sign_negative() {
            String::from("-0")
        } else {
            String::from("0")
        };
    }

    let scientific = format!("{:.*e}", SIGNIFICANT_DIGITS - 1, value);
    let (mantissa, exponent) = split_scientific(&scientific);

    if exponent < -4 || exponent >= SIGNIFICANT_DIGITS as i32 {
        return format!("{}e{:+03}", trim_fractional_zeros(mantissa), exponent);
    }

    let digits_after_decimal = (SIGNIFICANT_DIGITS as i32 - exponent - 1) as usize;
    trim_fractional_zeros(format!("{:.*}", digits_after_decimal, value))
}

fn split_scientific(text: &str) -> (&str, i32) {
    let (mantissa, exponent) = text.split_once('e').unwrap();
    (mantissa, exponent.parse::<i32>().unwrap())
}

fn trim_fractional_zeros(mut text: String) -> String {
    if text.contains('.') {
        while text.ends_with('0') {
            text.pop();
        }
        if text.ends_with('.') {
            text.pop();
        }
    }

    text
}

#[cfg(test)]
mod tests {
    use super::format_cpp_float;

    #[test]
    fn matches_defaultfloat_style_examples() {
        assert_eq!(format_cpp_float(0.42_f32), "0.42");
        assert_eq!(format_cpp_float(1.0_f32), "1");
        assert_eq!(format_cpp_float(0.000123456_f32), "0.000123456");
        assert_eq!(format_cpp_float(0.0000123456_f32), "1.23456e-05");
        assert_eq!(format_cpp_float(1_234_567.0_f32), "1.23457e+06");
    }

    #[test]
    fn preserves_special_values() {
        assert_eq!(format_cpp_float(f32::from_bits(0x8000_0000)), "-0");
        assert_eq!(format_cpp_float(f32::INFINITY), "inf");
        assert_eq!(format_cpp_float(f32::NEG_INFINITY), "-inf");

        let neg_nan = f32::from_bits(0xffc0_0000);
        assert_eq!(format_cpp_float(neg_nan), "-nan");
    }
}

